contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will take as parameters the distributor address, reward token address and amount to notify.
    // The function will try to call notifyRewardAmount and then assert the described invariant.
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0));
        // read pre-state
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforePerToken = c.rewardPerToken(rewardToken);

        bool reverted;
        // Try to call notifyRewardAmount; this call requires msg.sender == rewardDistributor in c
        // and that rewardData[rewardToken].lastUpdateTime != 0 and amount > 0.
        // We must call it as this contract (msg.sender for c will be this contract).
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterPerToken = c.rewardPerToken(rewardToken);

        // General rule:
        // If the call reverted, then nothing observable should have advanced: rewardPeriodFinish and rewardPerToken remain equal to before values.
        // If the call succeeded, then periodFinish must be >= block.timestamp and lastUpdateTime must be <= periodFinish and rewardPerToken may have changed.
        // We cannot read lastUpdateTime directly, so we check that afterFinish >= block.timestamp and afterFinish > beforeFinish || afterPerToken != beforePerToken.
        // Combine into single assert covering both cases.
        assert(
            (reverted && afterFinish == beforeFinish && afterPerToken == beforePerToken)
            || (!reverted && afterFinish >= uint40(block.timestamp) && (afterFinish > beforeFinish || afterPerToken != beforePerToken))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    // from - the address that will be the msg.sender for safeTransferFrom in staking (in this harness msg.sender is this contract, so stakeFor will attempt to pull tokens from this contract).
    // to - the beneficiary to receive the stake (passed to stakeFor)
    // amount - amount to stake
    // NOTE: In the actual environment the ERC20 token behavior is external; we only observe c's public getters.
    function run(address to, uint256 amount) public payable {
        require(to != address(0));
        // Observe pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(to);

        bool reverted;
        // Call stakeFor; it will use msg.sender == address(this) for safeTransferFrom
        // We catch reverts to distinguish outcomes
        try c.stakeFor(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(to);

        // General rule:
        // If stakeFor reverted then totalSupply and balanceOf(to) must remain equal to their before values.
        // If stakeFor succeeded then totalSupply increased by exactly amount and balanceOf(to) increased by exactly amount.
        assert(
            (reverted && afterTotal == beforeTotal && afterBal == beforeBal)
            || (!reverted && afterTotal == beforeTotal + amount && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

