contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: staker address, amount to stake
    function run(address staker, uint256 amount) public payable {
        require(amount > 0, "amount must be >0");

        // Ensure the test contract has enough tokens to transferFrom: caller of stakeFor is msg.sender (this contract)
        // So approve must be done by the token holder; here we assume this contract already holds tokens and approves c.
        // To satisfy observable checks, we will read before-values.

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeTokenBal = address(c).balance; // unrelated but allowed

        // Also observe token balances: this contract and c
        uint256 testContractTokenBefore = token.balanceOf(address(this));
        uint256 cTokenBefore = token.balanceOf(address(c));

        // We need to transfer tokens to this contract and approve c to pull them.
        // But we may only interact with public surface of c. We can transfer tokens to this contract via token.transfer if this contract already has tokens — cannot ensure.
        // Instead exploit stakeFor: it calls stakingToken.safeTransferFrom(msg.sender, address(this), _amount);
        // msg.sender will be this contract (InvMutTest), so this contract must have allowance set for c? No, safeTransferFrom pulls from msg.sender using token.transferFrom; token.transferFrom uses allowance of msg.sender towards c — but msg.sender is this contract, owner must have approved c which is impossible.
        // To work within constraints, we instead call c.stakeFor with msg.sender = this contract, but requirement: stakeFor takes tokens from msg.sender. So to make it not revert, we require that token.allowance(address(this), address(c)) >= amount and token.balanceOf(address(this)) >= amount. We cannot set those here, but we can require them as preconditions so the checker will supply appropriate state.

        require(token.allowance(address(this), address(c)) >= amount, "insufficient allowance for stakeFrom");
        require(token.balanceOf(address(this)) >= amount, "test contract lacks tokens to stake");

        // perform the operation: stakeFor(staker, amount) is public so we call via c.stakeFor
        bool reverted = false;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(staker);
        uint256 testContractTokenAfter = token.balanceOf(address(this));
        uint256 cTokenAfter = token.balanceOf(address(c));

        // If the call reverted then none of the state changes should have occurred on-chain.
        // General rule: if stakeFor succeeded, totalSupply and balanceOf(staker) increased by exactly amount,
        // and c's token balance increased by amount while this contract's token balance decreased by amount.
        // If it reverted, nothing changed.
        assert(
            (reverted && afterTotal == beforeTotal && afterBalance == beforeBalance && testContractTokenAfter == testContractTokenBefore && cTokenAfter == cTokenBefore)
            || (!reverted && afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount && testContractTokenAfter + amount == testContractTokenBefore && cTokenAfter == cTokenBefore + amount)
        );
    }

    receive() external payable {}
}

