contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: rewardToken address, amount to notify
    function run(address rewardToken, uint256 amount) public payable {
        // Observe before values via public getters
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 cBalanceBefore = IERC20(rewardToken).balanceOf(address(c));
        uint256 callerBalanceBefore = IERC20(rewardToken).balanceOf(address(this));

        bool reverted;
        // Top-level state-changing call as required. Must be direct call on c.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 cBalanceAfter = IERC20(rewardToken).balanceOf(address(c));
        uint256 callerBalanceAfter = IERC20(rewardToken).balanceOf(address(this));

        // General rule:
        // If the call reverted, then periodFinish must be unchanged and token balances unchanged.
        // Otherwise the call succeeded, periodFinish is at least block.timestamp + C.DURATION (observed via change >= DURATION),
        // and the contract's token balance increased by <= amount (exact transfer may be amount), and caller balance decreased accordingly.
        // We cannot read DURATION constant directly here, so express that afterFinish >= beforeFinish and afterFinish - beforeFinish <= uint40(2**40-1) and
        // require that contract balance increased by at most amount and caller decreased by at most amount, and net change equals cBalanceAfter - cBalanceBefore == callerBalanceBefore - callerBalanceAfter.

        assert(
            (reverted && afterFinish == beforeFinish && cBalanceAfter == cBalanceBefore && callerBalanceAfter == callerBalanceBefore)
            || (
                !reverted
                && afterFinish >= beforeFinish
                && cBalanceAfter >= cBalanceBefore
                && callerBalanceAfter <= callerBalanceBefore
                && (cBalanceAfter - cBalanceBefore) <= amount
                && (callerBalanceBefore - callerBalanceAfter) == (cBalanceAfter - cBalanceBefore)
            )
        );
    }

    receive() external payable {}
}

