contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
    }

    // We accept inputs: the reward token address, the distributor address, and an amount to notify.
    // The test will set reward distributor (onlyOwner) via the deployer owning c (the deployer is this test contract),
    // then add the reward token, have the distributor (simulated by calling setRewardDistributor to this contract and
    // then making the distributor call notifyRewardAmount). To call notifyRewardAmount from the distributor address
    // we instead set rewardDistributor to address(this) so the call originates from this contract.

    function run(address _rewardToken, uint256 _amount) public payable {
        require(_rewardToken != address(0));
        require(_amount > 0);

        // Precondition: this contract is the owner of c because the checker deploys a fresh C with this contract as creator.
        // Add the reward token so notifyRewardAmount recognizes it.
        c.addReward(_rewardToken);

        // Read previous periodFinish for the token
        uint40 prevFinish = c.rewardPeriodFinish(_rewardToken);

        // Ensure this contract is the distributor so notifyRewardAmount will accept our call
        c.setRewardDistributor(address(this));

        // Transfer _amount of the reward token from this test to c: but notifyRewardAmount expects the distributor to call
        // safeTransferFrom afterwards, so this contract must approve c to pull tokens. We cannot mint tokens here; instead
        // we rely on the caller providing a token contract that already has allowance/balance set for this contract.
        // To satisfy the constraint that we must only use c's public surface, we simply call notifyRewardAmount and catch reverts.

        bool reverted;
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 newFinish = c.rewardPeriodFinish(_rewardToken);
        // Check contract balance change observable: address(c).balance
        uint256 bal = address(c).balance;

        // General rule: if notifyRewardAmount did not revert then the periodFinish must have increased (be > prevFinish)
        // and the contract's Ether balance is unchanged by this call (notify uses ERC20 not Ether) — however the summary
        // asked for address(c).balance increases by the notified amount; that would be ERC20 balance not Ether. We cannot
        // observe ERC20 balances except via token contract, which is not allowed. So we assert the observable invariant:
        // if notifyRewardAmount succeeded then newFinish > prevFinish.

        assert(reverted || newFinish > prevFinish);
    }

    receive() external payable {}
}

