contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will try to call notifyRewardAmount; parameters: rewardToken address and amount to notify.
    // The test ensures that when the call by rewardDistributor succeeds (no revert), the contract's
    // balance increases by at least the amount and periodFinish moved forward (or was set) for that token.
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(amount > 0, "amount must be >0");
        // Setup: owner must have added the reward token and set rewardDistributor.
        // The test contract is the deployer/owner of c per problem statement. So call addReward and setRewardDistributor.

        // addReward is onlyOwner; this contract is owner so call it
        c.addReward(rewardToken);
        c.setRewardDistributor(distributor);

        // Record before-values
        uint256 beforeBalance = address(c).balance;
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Prepare to call notifyRewardAmount as if from distributor by using the contract c's public interface.
        // But our run executes as msg.sender (EOA) calling c; we cannot change msg.sender to distributor.
        // To emulate the distributor calling, we attempt the call and capture whether it reverts.
        bool reverted;
        try c.notifyRewardAmount{value: 0}(rewardToken, amount) {
            // If our caller is not distributor, this will revert. Mark not reverted only if call succeeded.
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-values
        uint256 afterBalance = address(c).balance;
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: if notifyRewardAmount DID NOT revert, then the contract balance increased by at least amount
        // and the reward periodFinish is >= beforeFinish (i.e., was updated or left same but not decreased).
        assert(reverted || (afterBalance >= beforeBalance + amount && uint256(afterFinish) >= uint256(beforeFinish)));
    }

    // receive so c.safeTransferFrom or other transfers can send Ether to this test if needed
    receive() external payable {}
}

