    constructor(C _c) { c = _c; }

    // call ERC20 balanceOf via public view function of C? Not available — use low-level staticcall directly in-run (allowed for view only)
    function run(address rewardToken, uint256 amount) public payable {
        require(true);

        // read balance before via low-level staticcall (view only)
        (bool b1, bytes memory d1) = rewardToken.staticcall(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), address(c)));
        uint256 beforeBalance = 0;
        if (b1 && d1.length >= 32) { beforeBalance = abi.decode(d1, (uint256)); }

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        (bool b2, bytes memory d2) = rewardToken.staticcall(abi.encodeWithSelector(bytes4(keccak256("balanceOf(address)")), address(c)));
        uint256 afterBalance = 0;
        if (b2 && d2.length >= 32) { afterBalance = abi.decode(d2, (uint256)); }

        // If the call did not revert then the contract's token balance increased by exactly amount
        assert(reverted || afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as inputs: the reward token address, the distributor address to set, and the amount to notify.
    // The test will: (1) ensure the reward token is added by owner, (2) set rewardDistributor, (3) transfer approval
    // and then call notifyRewardAmount from the distributor (we simulate by calling from this contract after setRewardDistributor
    // but note: notifyRewardAmount requires msg.sender == rewardDistributor, so we first set rewardDistributor to address(this)).
    // Because this test contract is the owner of freshly deployed C (per harness), owner-only calls succeed.

    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), true);
        // Add the reward token as owner
        c.addReward(rewardToken);

        // record before values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // set this contract as distributor so notifyRewardAmount can be called by us
        c.setRewardDistributor(address(this));

        // Transfer `amount` of rewardToken from msg.sender of this run (external account) to this contract so we can approve and call notify
        // However we cannot move tokens from external accounts in this test. Instead, we require that this contract already has the tokens
        // To safely call notifyRewardAmount we must ensure ERC20 transferFrom from this contract will succeed. The contract will call
        // IERC20(_rewardsToken).safeTransferFrom(msg.sender, address(this), _amount) inside notifyRewardAmount where msg.sender is address(this).
        // For that to work the token must have given allowance to this contract for itself or support direct transferFrom by holder==spender; in practice
        // many ERC20s allow transferFrom when from==msg.sender. To be conservative, we only proceed when amount > 0.
        require(amount > 0, "amount must be >0");

        // Call notifyRewardAmount from this contract (we are the rewardDistributor)
        bool reverted;
        try c.notifyRewardAmount{value: 0}(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule: If notifyRewardAmount did not revert, then afterFinish > beforeFinish and afterBalance == beforeBalance + amount.
        // If it reverted, we don't assert any relation — but the assert must be a general property over inputs and observed values.
        // We express: reverted || (afterFinish > beforeFinish && afterBalance == beforeBalance + amount)
        assert(reverted || (uint256(afterFinish) > uint256(beforeFinish) && afterBalance == beforeBalance + amount));
    }

    receive() external payable {}
}

