contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: who to stake for is implicit: msg.sender of stakeFor is this contract.
    // amount: amount to stakeFor (must be non-zero due to contract requirement)
    function run(uint256 amount) public payable {
        // Precondition: amount > 0 because stakeFor requires >0; if amount==0 the call always reverts.
        require(amount > 0, "amount>0");

        // Ensure this contract has approved c to pull tokens; the test actor can only interact via c and public functions.
        // We simulate providing tokens by transferring from this contract's token balance to itself is no-op; instead
        // we require this contract already has enough tokens so the subsequent safeTransferFrom can succeed when c pulls.
        // Check balances before
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTokenBalanceC = address(c).balance; // ETH balance of c (not used for ERC20)
        uint256 beforeTokenBalanceThis = token.balanceOf(address(this));

        bool reverted;
        // Try to call stakeFor; caller must have approved c to transferFrom. We cannot call token.approve here because
        // token is external ERC20 and this contract may not hold tokens. But we still must attempt and record revert.
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTokenBalanceThis = token.balanceOf(address(this));

        // If the stake succeeded (did not revert) then totalSupply and user's balance must increase by exactly amount
        // and this contract's ERC20 token balance must have decreased by at least amount (token transfer to c).
        // If it reverted then totalSupply and balance must be unchanged.
        assert(
            reverted
                ? (afterTotal == beforeTotal && afterBalance == beforeBalance)
                : (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount && beforeTokenBalanceThis >= afterTokenBalanceThis && beforeTokenBalanceThis - afterTokenBalanceThis >= amount)
        );
    }

    receive() external payable {}
}

