contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // addrDistributor: address to set as rewardDistributor (owner only call)
    // rewardToken: token address to register via addReward
    // amount: amount passed to notifyRewardAmount
    // callerIsDistributor: if true, call notifyRewardAmount from this contract (which will be the distributor);
    //                    otherwise first set rewardDistributor to some other address so call should revert
    function run(address addrDistributor, address rewardToken, uint256 amount, bool callerIsDistributor) public payable {
        require(address(this) != address(0));
        // ensure contract has allowance and balances are irrelevant for the proof; we only observe public state

        // First, make sure rewardToken is known by calling addReward as owner.
        // The InvMutTest contract is NOT owner by default; c was deployed by the checker and owner is msg.sender at deployment (the checker).
        // We cannot assume ownership. To still register a reward token, try-catch: if addReward reverts (not owner), we cannot proceed with notify; but rule must hold generally.

        bool added = false;
        try c.addReward(rewardToken) {
            added = true;
        } catch {
            added = false;
        }

        // Record pre-state: periodFinish (callable even if token unknown returns 0)
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Decide who is the distributor: if callerIsDistributor true, set rewardDistributor to this contract by calling setRewardDistributor.
        // setRewardDistributor is onlyOwner; attempt and record if succeeded.
        bool setDist = false;
        try c.setRewardDistributor(address(this)) {
            setDist = true;
        } catch {
            setDist = false;
        }

        // If callerIsDistributor is false and setting distributor to some other address is desired, attempt to set to addrDistributor.
        bool setDistOther = false;
        if (!callerIsDistributor) {
            try c.setRewardDistributor(addrDistributor) {
                setDistOther = true;
            } catch {
                setDistOther = false;
            }
        }

        // Now call notifyRewardAmount and capture revert
        bool reverted = false;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // The general rule we assert:
        // - If notifyRewardAmount did NOT revert, then the reward token must have been known (i.e., rewardData.lastUpdateTime != 0 reflected by beforeFinish != 0 OR added==true), and afterFinish >= block.timestamp.
        // - If notifyRewardAmount reverted, then at least one of the known revert reasons holds: caller wasn't distributor (we couldn't set distributor to this contract), or amount == 0, or reward token unknown.
        // We cannot inspect internal lastUpdateTime directly, so we use beforeFinish==0 as proxy for unknown token.

        assert(
            // case: call succeeded
            (!reverted && (afterFinish >= block.timestamp) && (
                // token was previously added (either able to add here or beforeFinish non-zero)
                (added || beforeFinish != uint40(0))
            ))
            // OR case: call reverted and at least one of the public-observable failure reasons is plausible
            || (reverted && (
                amount == 0 || // amount==0 causes revert
                // or distributor was not this contract (we failed to set it to this contract and callerIsDistributor intended true)
                (callerIsDistributor && !setDist) ||
                // or token unknown (beforeFinish == 0 and we couldn't add it)
                (beforeFinish == uint40(0) && !added)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // staker: address from which this contract will try to stake tokens for (we must be msg.sender for stakingToken.safeTransferFrom to work);
    // amount: amount to stake and then withdraw;
    // claim: whether to claim rewards on withdraw
    function run(address staker, uint256 amount, bool claim) public payable {
        require(address(this) != address(0));

        // Record pre-state: balanceOf for this contract (as staker) and totalSupply
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTotal = c.totalSupply();

        // Try to stake amount by calling stakeFor — this will attempt a transferFrom from msg.sender (this contract)
        bool stakeReverted;
        try c.stakeFor(address(this), amount) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // After attempting stake, read balances
        uint256 midBalance = c.balanceOf(address(this));
        uint256 midTotal = c.totalSupply();

        // Now attempt to withdraw 'amount' and capture whether it reverts
        bool withdrawReverted;
        try c.withdraw(amount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read post-state
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTotal = c.totalSupply();
        uint256 contractEthBalance = address(c).balance;

        // General rule asserted:
        // If withdraw did not revert then:
        //   - afterBalance == midBalance - amount
        //   - afterTotal == midTotal - amount
        //   (i.e., withdraw reduced both by amount)
        // If withdraw reverted then at least one of these public-observable reasons holds:
        //   - amount == 0 (contract reverts with "Cannot withdraw 0")
        //   - midBalance < amount (Not enough staked tokens)
        // Note: If stake itself reverted then midBalance == beforeBalance and midTotal == beforeTotal.

        assert(
            (!withdrawReverted && afterBalance + amount == midBalance && afterTotal + amount == midTotal)
            || (withdrawReverted && (amount == 0 || midBalance < amount))
        );
    }

    receive() external payable {}
}

