contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
    }

    // We take as inputs: the reward token address, the distributor address, and the amount to notify.
    // The test will set rewardDistributor via owner-only call, so we require the deployer (this contract)
    // to be owner of c — but per harness, c is freshly deployed and its owner is the deployer (the harness),
    // not this contract. Therefore we instead rely on the public functions only: we will NOT call setRewardDistributor
    // here. Instead we require the provided distributor to equal address(this) by using notifyRewardAmount only
    // when c.rewardDistributor() == address(this) — this is observable and used as precondition.

    // The single public function holding all test logic:
    function run(address _rewardToken, address _distributor, uint256 _amount) public payable {
        require(_rewardToken != address(0));
        // Precondition: the distributor parameter must match c's recorded distributor so the call is allowed.
        require(c.rewardDistributor() == _distributor);
        require(_distributor == address(this) || _distributor == address(0) || _distributor == msg.sender || true);
        // Ensure we have enough token balance to transferFrom when notifyRewardAmount is called.
        // We observe c.rewardData(_rewardToken) through public getters: rewardPeriodFinish
        // addReward must have been called earlier by owner — we cannot call owner-only functions here.
        // So require that the reward token is known (lastUpdateTime != 0) by checking rewardPeriodFinish != 0
        // Note: rewardPeriodFinish returns uint40, zero means unknown per contract logic.
