    IERC20 token;

    constructor(C _c) {
        c = _c;
        // infer staking token from deployed contract's public getter
        token = c.stakingToken();
    }

    // params: who to stake for, amount to stake. This function will try to approve and then call stakeFor.
    function run(address forAddr, uint256 amount) public payable {
        require(address(this) != address(0));

        // Capture pre-state
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddr);
        uint256 myTokenBal = token.balanceOf(address(this));

        // To perform stakeFor we must transfer tokens from msg.sender (this contract). Ensure we have tokens.
        // The test harness may not have tokens; if not enough balance then we skip calling stakeFor by expecting revert when amount>myTokenBal.

        // Approve c to pull tokens if we have balance
        if (myTokenBal >= amount) {
            // approve via IERC20 interface exposed on token
            token.approve(address(c), amount);
        }

        bool reverted;
        // perform the call and capture revert
        try c.stakeFor(forAddr, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddr);

        // General rule asserted:
        // - If amount == 0 then stakeFor must revert (Cannot stake 0). If it didn't revert, then totals must be unchanged.
        // - If amount > 0 and this test had sufficient token balance and approved, then stakeFor should not revert and totalSupply and balanceOf(forAddr) increase by exactly amount.
        // - If amount > 0 but this contract lacked tokens/approval, stakeFor may revert; in that case total and balance must be unchanged.

        assert(
            // case amount == 0: must revert OR have no state change
            (
                amount == 0 && (reverted || (totalAfter == totalBefore && balAfter == balBefore))
            )
            ||
            // case we had tokens and approved: should succeed and increase both by amount
            (
                amount > 0 && myTokenBal >= amount && !reverted && totalAfter == totalBefore + amount && balAfter == balBefore + amount
            )
            ||
            // case we didn't have tokens/approval: allowed to revert and state must be unchanged
            (
                amount > 0 && myTokenBal < amount && (reverted || (totalAfter == totalBefore && balAfter == balBefore))
            )
        );
    }

    receive() external payable {}
}

