    // Preconditions: none about balances/approvals in c; we observe before/after and whether call reverted.
    function run(uint256 amount, bool claim) public payable {
        // Observe before values for this contract's address as staker
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeCbalance = address(c).balance;

        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterCbalance = address(c).balance;

        // General rule: if withdraw did not revert then totalSupply and the caller's balance decreased by exactly amount,
        // and the contract's ETH balance may change only if stakingToken.transfer triggers transfers of ETH (not expected),
        // but we assert the deterministic token-accounting effect observed via public getters.
        assert(reverted || (beforeTotal >= amount && beforeBalance >= amount && afterTotal == beforeTotal - amount && afterBalance == beforeBalance - amount));
    }

    receive() external payable {}
}

