contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: distributor calls notifyRewardAmount on c; we simulate by having this contract be the distributor
    // We require that the reward token has already been added by the owner. Since the fresh c is deployed by the checker
    // and owner() is msg.sender at construction of C, our test cannot be owner. So we instead assume owner has added
    // a reward token and set rewardDistributor to this contract. To make a meaningful property we will only call
    // notifyRewardAmount when rewardData for the token is known (rewardPeriodFinish() != 0).
    // The function takes the reward token address and the amount to notify, and attempts to assert that
    // periodFinish increases and the c contract holds tokens (observed via IERC20.balanceOf but we can not call
    // IERC20 here; instead we observe via calling rewardPeriodFinish and rely on the transfer reverting or not.

    // To observe token transfer effect we rely on calling notifyRewardAmount which will in turn call
    // IERC20(_rewardsToken).safeTransferFrom(msg.sender, address(this), _amount);
    // That call will succeed only if this contract has approved c to pull tokens. We cannot set approvals for arbitrary tokens.
    // Instead we'll assert a general relation between previous and new periodFinish and that notifyRewardAmount reverts iff
    // the call didn't satisfy distributor requirement or token unknown or amount==0.

    // We craft the property: If notifyRewardAmount does NOT revert when called by rewardDistributor (msg.sender == rewardDistributor),
    // then rewardPeriodFinish(token) after the call is > rewardPeriodFinish(token) before the call.

    // The test function will attempt the call and record whether it reverted, and compare periodFinish values accordingly.

    function run(address rewardToken, uint256 amount) public payable {
        require(true);

        // Read before value
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Attempt to call notifyRewardAmount from this contract.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: If the call did not revert, then the periodFinish must have increased (strictly greater)
        // If the call reverted, we make no requirement about periodFinish.
        assert(reverted || (afterFinish > beforeFinish));
    }

    receive() external payable {}
}

