contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will check that stakeFor(_for, amount) when amount>0 either reverts or results
    // in totalSupply and balanceOf(_for) both increased by exactly amount and that the
    // staking token balance of this contract increases by amount (tracking the token transfer).
    // Inputs: caller supplies two addresses and an amount. msg.sender for token transfers
    // is this contract (the InvMutTest) when we call c.stakeFor because the deployed c sees
    // InvMutTest as msg.sender. We cannot mint tokens here; the checker deploys c with some
    // staking token. We conservatively require amount>0.

    function run(address beneficiary, address tokenHolder, uint256 amount) public payable {
        require(amount > 0);

        // Observe pre-state
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(beneficiary);

        // Observe staking token balance of c before via public stakingToken getter then IERC20(balanceOf)
        address stakingTok = address(c.stakingToken());
        uint256 contractTokenBalBefore = IERC20(stakingTok).balanceOf(address(c));
        uint256 senderTokenBalBefore = IERC20(stakingTok).balanceOf(address(this));

        // We will attempt to call stakeFor. It may revert (e.g., due to insufficient allowance/balance).
        bool didRevert = false;
        try c.stakeFor{ value: 0 }(beneficiary, amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(beneficiary);
        uint256 contractTokenBalAfter = IERC20(stakingTok).balanceOf(address(c));
        uint256 senderTokenBalAfter = IERC20(stakingTok).balanceOf(address(this));

        // General rule: if the call did not revert then totalSupply and beneficiary balance
        // must have increased exactly by amount, and the token balance of the staking contract
        // must have increased by amount (the token was transferred from this contract to c).
        // If it reverted, none of those deltas should be required.
        assert(didRevert ||
            (totalAfter == totalBefore + amount
             && balAfter == balBefore + amount
             && contractTokenBalAfter == contractTokenBalBefore + amount
             && senderTokenBalAfter + amount == senderTokenBalBefore));
    }

    // Minimal interfaces used for token balance checks
    receive() external payable {}
}

